import RNA, random, time, sys

target='(.(((..(((((....(((((......))))))))))((((...((((.....))))))))(((..(((....)))))).(((...((((...((((......))))))))(((..(((.....))))))((.((....)))).((((....(((..(((......))))))((.((.....))))(((....))).(((((.....((.((......))))(((.....)))((....)).((((((......(((......)))((.....))...(((((((...))))))).......))))))......))))).....))))....)))...)))..)...(.((.((((....((....))((....))((((((...)))))).)))))).)'
N=len(target)
pairs={}
stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
comp={'A':'U','U':'A','C':'G','G':'C'}

start=''

def get_pairs(ss):
    st=[]; ps=set()
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')': ps.add((st.pop(),i))
    return ps
tp=get_pairs(target)

def bpdist(seq):
    fc=RNA.fold_compound(seq); ss,mfe=fc.mfe()
    sp=get_pairs(ss)
    return len(tp^sp), ss

seed=int(sys.argv[1])
best=start; best_d,_=bpdist(start)
random.seed(seed)
deadline=time.time()+110
unpaired=set(range(N))-set(pairs.keys())
it=0
while time.time()<deadline and best_d>0:
    it+=1
    d,ss=bpdist(best)
    if d==0: break
    sp=get_pairs(ss)
    missing=tp-sp; spurious=sp-tp
    cur=list(best)
    for (i,j) in list(missing):
        cur[i]=random.choice(['G','C']); cur[j]=comp[cur[i]]
    for (i,j) in list(spurious):
        a=random.choice([i,j]); cur[a]=random.choice(['A','U'])
    for _ in range(random.randint(1,5)):
        p=random.randrange(N)
        if p not in pairs: cur[p]=random.choice('ACGU')
    new=''.join(cur)
    nd,_=bpdist(new)
    if nd<best_d or (nd==best_d and random.random()<0.5):
        best=new; best_d=nd
sys.stderr.write(f'seed{seed} best {best_d} iters {it}\n'); sys.stderr.flush()
sys.stdout.write(best+'\n'); sys.stdout.flush()
PYEOF
